class Engine:
    def start(self):
        return "vroom"

class Car:
    def __init__(self):
        self.engine = Engine()

    def start(self):
        return self.engine.start()

print(Car().start())

class Driver:
    pass

class Page:
    def __init__(self, driver):
        self.driver = driver

p = Page(Driver())
isinstance(p, Driver)

class FakeApi:
    def get(self):
        return "stub"

class Service:
    def __init__(self, api):
        self.api = api

    def fetch(self):
        return self.api.get()

print(Service(FakeApi()).fetch())

class Wheels:
    def roll(self):
        return "rolling"

class Truck:
    def __init__(self):
        self.wheels = Wheels()

t = Truck()
print(t.roll())

class Logger:
    def info(self, m):
        return f"INFO {m}"

class App:
    def __init__(self):
        self.log = Logger()

    def __getattr__(self, name):
        return getattr(self.log, name)

print(App().info("up"))

class Store:
    def save(self, x):
        return len(x)

class DbStore(Store):
    pass

def use(store):
    return store.save("abc")

use(DbStore()) == use(Store())

class Db:
    def query(self):
        return ["row"]

class Report:
    def __init__(self, db):
        self.db = db

r = Report(Db)
print(r.db.query())
